/* Function to enable the data read access to a predefined Range in a Protection Set */
void CPU_CORE_EnableDataRead(uint32 protection_set, uint32 range)
{
  Ifx_CPU_DPRE DPRE_value;

  /* Get the CPU Data Protection Read Enable Register value */
  switch (protection_set)
  {
    case 0: /* Protection Set 0 */
      DPRE_value.U = __mfcr(CPU_DPRE_0);
      break;
    case 1: /* Protection Set 1 */
      DPRE_value.U = __mfcr(CPU_DPRE_1);
      break;
    case 2: /* Protection Set 2 */
      DPRE_value.U = __mfcr(CPU_DPRE_2);
      break;
    case 3: /* Protection Set 3 */
      DPRE_value.U = __mfcr(CPU_DPRE_3);
      break;
    case 4: /* Protection Set 4 */
      DPRE_value.U = __mfcr(CPU_DPRE_4);
      break;
    case 5: /* Protection Set 5 */
      DPRE_value.U = __mfcr(CPU_DPRE_5);
      break;
#if CPU_CORE_TCX == CPU_CORE_TC4
    case 6: /* Protection Set 6 */
      DPRE_value.U = __mfcr(CPU_DPRE_6);
      break;
    case 7: /* Protection Set 7 */
      DPRE_value.U = __mfcr(CPU_DPRE_7);
      break;
#endif
    default:
      /* Invalid range */
      break;
  }

  /* Set the bit corresponding to the given Data Protection Range */
#if CPU_CORE_TCX == CPU_CORE_TC3
  DPRE_value.B.RE_N |= (1 << range);
#else
  DPRE_value.U |= (0x01 << range);
#endif

  /* Set the CPU Data Protection Read Enable Register value to enable data read access */
  switch (protection_set)
  {
    case 0: /* Protection Set 0 */
      __mtcr(CPU_DPRE_0, DPRE_value.U);
      break;
    case 1: /* Protection Set 1 */
      __mtcr(CPU_DPRE_1, DPRE_value.U);
      break;
    case 2: /* Protection Set 2 */
      __mtcr(CPU_DPRE_2, DPRE_value.U);
      break;
    case 3: /* Protection Set 3 */
      __mtcr(CPU_DPRE_3, DPRE_value.U);
      break;
    case 4: /* Protection Set 4 */
      __mtcr(CPU_DPRE_4, DPRE_value.U);
      break;
    case 5: /* Protection Set 5 */
      __mtcr(CPU_DPRE_5, DPRE_value.U);
      break;
#if CPU_CORE_TCX == CPU_CORE_TC4
    case 6: /* Protection Set 6 */
      __mtcr(CPU_DPRE_6, DPRE_value.U);
      break;
    case 7: /* Protection Set 7 */
      __mtcr(CPU_DPRE_7, DPRE_value.U);
      break;
#endif
    default:
      /* Invalid range */
      break;
  }

#if !defined(__TASKING__)
  __isync();
#endif
}

