/* Function to configure MPU */
void CPU_CORE_ConfigureMpu(CPU_CORE_MPU_CONF_t * mpu_config)
{
  /* Configure data ranges */
  for (uint32 i = 0; i < mpu_config->data_range.num; i++)
  {
    CPU_CORE_DefineDataProtectionRange(mpu_config->data_range.ranges[i].start, mpu_config->data_range.ranges[i].end, i);
  }

  /* Configure code ranges */
  for (uint32 i = 0; i < mpu_config->code_range.num; i++)
  {
    CPU_CORE_DefineCodeProtectionRange(mpu_config->code_range.ranges[i].start, mpu_config->code_range.ranges[i].end, i);
  }

  /* Configure protection sets */
  for (uint32 i = 0; i < mpu_config->set.num; i++)
  {
    for (uint32 j = 0; j < mpu_config->data_range.num; j++)
    {
      if (mpu_config->set.sets[i].read & (1 << j))
      {
        CPU_CORE_EnableDataRead(i, j);
      }
      if (mpu_config->set.sets[i].write & (1 << j))
      {
        CPU_CORE_EnableDataWrite(i, j);
      }
    }
    for (uint32 j = 0; j < mpu_config->code_range.num; j++)
    {
      if (mpu_config->set.sets[i].execute & (1 << j))
      {
        CPU_CORE_EnableCodeExecution(i, j);
      }
    }
  }

  /* Activate Protection Set 0.
   * The active protection set determines the read, write, and execute permissions of the CPU.
   */
  CPU_CORE_SetActiveProtectionSetCore(0);

  /* Enable the Memory Protection */
  CPU_CORE_EnableMemoryProtection();
}

