{
#if CPU_CORE_TCX == CPU_CORE_TC3
  Ifx_CPU_SYSCON syscon_value;
  syscon_value.U = __mfcr(CPU_SYSCON);              /* Get the System Configuration Register (SYSCON) value     */
  syscon_value.B.U1_IOS = iomode_config.u1_ios;     /* Set the U1_IOS bitfield to control the User-1 Peripheral access as supervisor */
  syscon_value.B.U1_IED = iomode_config.u1_ied;     /* Set the U1_IED bitfield to control the User-1 Instruction execution disable */
  __mtcr(CPU_SYSCON, syscon_value.U);               /* Set the System Configuration Register (SYSCON)           */
#else
  Ifx_CPU_CORECON coreconValue;
  coreconValue.U = __mfcr(CPU_CORECON);             /* Get the Core Configuration Register (CORECON) value     */
  coreconValue.B.U1_IOS = iomode_config.u1_ios;     /* Set the U1_IOS bitfield to control the User-1 Peripheral access as supervisor */
  coreconValue.B.U1_IED = iomode_config.u1_ied;     /* Set the U1_IED bitfield to control the User-1 Instruction execution disable */
  __mtcr(CPU_CORECON, coreconValue.U);              /* Set the Core Configuration Register (CORECON)           */
#endif

#if !defined(__TASKING__)
  __isync();
#endif
}

